CONDITION_EXAMPLES = [
    {
        "question": "Is the sky blue?",
        "answer": "True"
    },
    {
        "question": "Do humans have three arms?",
        "answer": "False"
    },
    {
        "question": "Is water wet?",
        "answer": "True"
    },
]

CONDITION_EXAMPLE_PROMPT = PromptTemplate(template="""
Question:
{question}

Answer:
{answer}
---------
""", input_variables=["question", "answer"])

CONDITION_PROMPT = FewShotPromptTemplate(
    prefix="Determine whether the following statement is true or false. Only reply by true or false and nothing else. {instruction_hint}",
    examples=CONDITION_EXAMPLES,
    example_prompt=CONDITION_EXAMPLE_PROMPT,
    suffix="Question:\n{question}\nAnswer:",
    input_variables=["instruction_hint", "question"]
)


class ConditionOutputParser(BaseOutputParser[Union[bool, str]]):

    def parse(self, text: str) -> Union[bool, str]:
        text = text.strip().lower()
        if text == "true":
            return True
        elif text == "false":
            return False
        else:
            return "Wrong format of the answer"


class ConditionChain(LLMChain):
    def __init__(self, **kwargs):
        super().__init__(prompt=CONDITION_PROMPT, **kwargs)

    def predict(self, question: str, instruction_hint: str = '', **kwargs: Any) -> bool:
        result = super().predict(question=question, instruction_hint=instruction_hint, **kwargs)
        return ConditionOutputParser().parse(result)


class ConditionMixin:
    condition_chain: ConditionChain

    def condition(self, question: str, instruction_hint: str = '') -> bool:
        return self.condition_chain.predict(question=question, instruction_hint=instruction_hint)


if __name__ == '__main__':
    chain = ConditionChain(llm=ChatOpenAI(model_name="gpt-3.5-turbo"))
    print(chain.predict(question="Is 2+2 equal to 4?", instruction_hint=""))

from typing import Dict, List, Any, Union, Optional

from langchain import PromptTemplate, LLMChain
from langchain.schema import LLMResult, BaseOutputParser, Generation
from langchain.llms import OpenAI, BaseLLM
from langchain.prompts.few_shot import FewShotPromptTemplate
from langchain.chat_models import ChatOpenAI

SELECT_EXAMPLES = [
    {
        "question": "Which animal is known as the king of the jungle?",
        "options_text": '\n'.join(["Lion", "Elephant", "Tiger", "Giraffe"]),
        "answer": "Lion"
    },
    {
        "question": "What color do you get when you mix blue and yellow?",
        "options_text": '\n'.join(["Green", "Orange", "Purple", "Brown"]),
        "answer": "Green"
    },
    {
        "question": "Which animal is a carnivore?",
        "options_text": '\n'.join(["Lion", "Elephant", "Tiger", "Giraffe"]),
        "answer": "Lion\nTiger"
    },
    {
        "question": "Which of these are plants?",
        "options_text": '\n'.join(["Lily", "Giraffe", "Cactus", "Rose"]),
        "answer": "Lily\nGiraffe\nCactus\nRose"
    },
]

SELECT_EXAMPLE_PROMPT = PromptTemplate(template="""
Question:
{question}

Options:
{options_text}

Answer:
{answer}
---------
""", input_variables=["question", "options_text", "answer"])


def format_options(options: List[str]) -> str:
    return "\n".join(options)




class SelectOutputParser(BaseOutputParser[List[str]]):
    options: List[str]

    def parse(self, text: str) -> List[str]:
        results = []
        answers = text.split('\n')
        for answer in answers:
            if answer.strip().lower() in [option.lower() for option in self.options]:
                results.append(answer.strip())
        return results


class SelectChain(LLMChain):
    def __init__(self, select_examples: Optional[List] = None, **kwargs):
        SELECT_PROMPT = FewShotPromptTemplate(
            prefix="Choose the correct answer(s) for the following question from the provided options. If there are "
                   "many answers, return each one in a separate line. {num_choices_hint}",
            examples=select_examples or SELECT_EXAMPLES,
            example_prompt=SELECT_EXAMPLE_PROMPT,
            suffix="{instruction_hint}\nQuestion:\n{question}\nOptions:\n{options_text}\nAnswer:\n",
            input_variables=["instruction_hint", "question", "options_text", "num_choices_hint"]
        )
        super().__init__(prompt=SELECT_PROMPT, **kwargs)

    def predict(self, question: str, options: List[str], instruction_hint: str = '', num_choices: int = None, **kwargs: Any) -> List[str]:
        num_choices_hint = f"Return exactly {num_choices} answer" if num_choices else ''
        options_text = format_options(options)
        result = super().predict(question=question, options_text=options_text, instruction_hint=instruction_hint, num_choices_hint=num_choices_hint,
                                 **kwargs)
        return SelectOutputParser(options=options).parse(result)


class SelectMixin:
    select_chain: SelectChain

    def select(self, question: str, options: List[str], instruction_hint: str = '', select_chain: Optional[SelectChain] = None, num_choices: int = None) -> List[str]:
       chain = select_chain or self.select_chain
       return chain.predict(question=question, options=options, instruction_hint=instruction_hint, num_choices=num_choices)


if __name__ == '__main__':
    chain = SelectChain(llm=ChatOpenAI(model_name="gpt-3.5-turbo"))
    print(chain.predict(question="Which animal is known as the king of the jungle?",
                        options=["Lion", "Elephant", "Tiger", "Giraffe"], instruction_hint=""))

import warnings
from typing import Dict, List, Any

from langchain import PromptTemplate, LLMChain
from langchain.llms import OpenAI, BaseLLM
from langchain.prompts.few_shot import FewShotPromptTemplate
from langchain.chat_models import ChatOpenAI

from thinkgpt.helper import LineSeparatorOutputParser

INFERENCE_EXAMPLE_PROMPT = PromptTemplate(template="""
Facts:
{facts}

New Observations:
{new_observations}
---------
""", input_variables=["facts", "new_observations"])

examples = [
    {
        "facts": '\n'.join([
            "water boils at 100 degrees Celsius",
            "water freezes at 0 degrees Celsius",
        ]),
        "new_observations": '\n'.join([
            "ice can be formed by cooling water to 0 degrees Celsius or below",
            "steam can be produced by heating water to 100 degrees Celsius or above",
        ])
    },
    {
        "facts": '\n'.join([
            "plants need sunlight, water, and carbon dioxide to perform photosynthesis",
            "photosynthesis is the process by which plants produce glucose and oxygen",
        ]),
        "new_observations": '\n'.join([
            "a plant placed in a dark room will not be able to perform photosynthesis and may eventually die",
            "providing a plant with enough sunlight, water, and carbon dioxide will help it grow and produce oxygen",
        ])
    },
]

INFERENCE_PROMPT = FewShotPromptTemplate(
    prefix="Based on the following facts, infer new observations. Put each new observation in a separate line. {instruction_hint}",
    examples=examples,
    example_prompt=INFERENCE_EXAMPLE_PROMPT,
    suffix="Facts:\n{facts}\nNew Observations:",
    input_variables=["instruction_hint", "facts"]
)


class InferChain(LLMChain):
    """Prompts the LLM to generate new observations based on the given facts"""
    def __init__(self, **kwargs):
        super().__init__(prompt=INFERENCE_PROMPT, **kwargs)

    def predict(self, instruction_hint: str = '', **kwargs: Any) -> str:
        return super().predict(instruction_hint=instruction_hint, **kwargs)


class InferMixin:
    infer_chain: InferChain

    def infer(self, facts: List[str], instruction_hint: str = '') -> List[str]:
        result = self.infer_chain.predict(
            facts="\n".join(facts), instruction_hint=instruction_hint
        )
        return LineSeparatorOutputParser().parse(result)


if __name__ == '__main__':
    chain = InferChain(llm=ChatOpenAI(model_name="gpt-3.5-turbo"))
    # examples from the paper https://arxiv.org/abs/2304.03442
    print(chain.predict(facts="\n".join([
        "Klaus Mueller is writing a research paper",
        "Klaus Mueller enjoys reading a book on gentrification",
        "Klaus Mueller is conversing with Ayesha Khan about exercising"
    ])))
